mapper.select:
SELECT P.PORTFOLIO_ID id, P.PORTFOLIO_NAME text, TO_CHAR(P.VDATE,'YYYY-MM-DD') object FROM PTL_PORTFOLIO P LEFT JOIN PTL_PORTFOLIO_AUTHORITY AU ON P.PORTFOLIO_ID = AU.PORTFOLIO_ID
AND (P.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR P.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{initValue}
AND AU.USER_ID = #{userId}
AND P.PORTFOLIO_TYPE = #{PORT_TYPE}

SELECT deal.trade_id busiNo, S.BUSI_ACCT_NO busiAcctNo, S.Acct_Name acctName, S.ACCT_NO acctNo, P.PORTFOLIO_ID portfolioId, nvl(deal.ccy, P.CCY) ccy, PTL.PORTFOLIO_NAME portfolioName, VAL.TDY_INTINCEXP theoryTradeAmt, nvl(deal.trade_amt , 0) actualTradeAmt, CASE WHEN (SELECT count(0) from PTL_PORTFOLIO PTL1 where PTL.PORTFOLIO_ID = PTL1.PARENT_PORTFOLIO_ID) > 0 THEN 'Y' ELSE 'N' END isParentPortfolio, S.BANK_DEP bankDep FROM PTL_CAPACCT_INFO P INNER JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO AND P.CCY = S.CCY INNER JOIN PTL_SEC_VALUTION VAL ON VAL.PORTFOLIO_ID = P.PORTFOLIO_ID AND VAL.FINPROD_ID = P.ACCT_NO AND VAL.CDATE = to_date(#{mdate},'yyyy-mm-dd')-1 INNER JOIN FIN_PRODUCT_ADD AD ON AD.PORTFOLIO_ID = P.PORTFOLIO_ID INNER JOIN FIN_PRODUCT FIN ON FIN.FINPROD_ID = AD.FINPROD_ID AND FIN.FINPROD_TYPE2 = #{FINPROD_TYPE2_F16} INNER JOIN PTL_PORTFOLIO PTL ON P.PORTFOLIO_ID = PTL.PORTFOLIO_ID
/*modify by caojin TISHKBS-631 双击查看明细信息重复 2020/6/6 start */ left join ( select deal.trade_id,deal.finprod_id,deal.ccy,deal.trade_amt,dealadd.PORTFOLIO_ID from trd_Product_Deal deal left join trd_Product_Deal_add dealadd ON deal.trade_id = dealadd.trade_id AND deal.totle_trade_id = #{busiNo} ) deal on s.acct_no = deal.finprod_id and deal.PORTFOLIO_ID = P.PORTFOLIO_ID /*modify by caojin TISHKBS-631 双击查看明细信息重复 2020/6/6 end */
1=1
AND ( S.BUSI_ACCT_NO IN
null) or S.BUSI_ACCT_NO in ( #{item} )
/*modify by caojin TISHKBS-631 双击查看无明细信息 2020/6/5 start */ /*AND NOT EXISTS ( SELECT *FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL WHERE TOTAL.FINPROD_ID = S.ACCT_NO
)*/ /*modify by caojin TISHKBS-631 双击查看无明细信息 2020/6/5 end */

	SELECT 
    	TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID code
    	/*多级法人改造  添加seqno字段   add by caojin  2020/6/20   start*/
    	,STL_CAPACCT_INFO.SEQ_NO seqno
    	/*多级法人改造  添加seqno字段   add by caojin  2020/6/20   end*/
	FROM TRD_FIN_PRODUCT_DEAL_TOTAL
	left join STL_CAPACCT_INFO
	on TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_ID = STL_CAPACCT_INFO.ACCT_NO


    		AND TOTLE_TRADE_ID LIKE CONCAT('%',CONCAT(#{param},'%') )


			AND BUSI_TYPE = #{busiType}

			AND IS_CANCEL != #{yesOrNo_Y}
			AND TRADE_STATUS = #{TRADE_STATUS_01}

SELECT P.PORTFOLIO_ID code, P.PORTFOLIO_NAME shortName， TO_CHAR(P.VDATE,'YYYY-MM-DD') hidCode FROM PTL_PORTFOLIO P LEFT JOIN PTL_PORTFOLIO_AUTHORITY AU ON P.PORTFOLIO_ID = AU.PORTFOLIO_ID
AND (P.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{param},'%')) OR P.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{param},'%')))
AND P.PORTFOLIO_ID = #{initValue}
AND AU.USER_ID = #{userId}
AND P.PORTFOLIO_TYPE = #{PORT_TYPE}

select distinct S.BANK_DEP id, S.BANK_DEP text FROM PTL_CAPACCT_INFO P INNER JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO AND P.CCY = S.CCY
INNER JOIN DATA_AUTH_NOTIFY_INST di on di.BUSINESS_ID = S.seq_No AND di.MODEL_TYPE = '02' and di.data_type = 'MST09' AND di.INSTITUTION_CODE IN
#{item}
WHERE 1 = 1
AND S.BANK_DEP LIKE CONCAT('%',CONCAT(#{search},'%'))
AND S.BANK_DEP = #{initValue}

	SELECT 
    	ACCT_NO acctNo
	FROM STL_CAPACCT_INFO
	WHERE 
     	BUSI_ACCT_NO = #{myAcctNo,jdbcType=VARCHAR}
     	AND CCY = #{ccy,jdbcType=VARCHAR}

	SELECT 
    	ACCT_NAME getAcctName
	FROM STL_CAPACCT_INFO
	WHERE 
     	BUSI_ACCT_NO = #{myAcctNo,jdbcType=VARCHAR}
     	AND CCY = #{ccy,jdbcType=VARCHAR}
     	AND ACCT_NO = #{acctNo}

	SELECT 
	    TO_CHAR(MAX(T.MDATE),'yyyy-mm-dd')
	FROM TRD_FIN_PRODUCT_DEAL_TOTAL T 
	  INNER JOIN
	       STL_CAPACCT_INFO S
	  ON T.FINPROD_ID = S.ACCT_NO
	WHERE 1=1

     	AND S.BUSI_ACCT_NO = #{acctNo}

	AND T.TRADE_STATUS = #{TRADE_STATUS_01}
    AND T.IS_CANCEL = #{YES_OR_NO_N}

SELECT AD.PROD_REGIST_CODE FROM FIN_PRODUCT FIN INNER JOIN FIN_PRODUCT_ADD AD ON FIN.FINPROD_ID = AD.FINPROD_ID
AND FIN.FINPROD_MARKET_ID = #{portfolioId}
AND FIN.FINPROD_TYPE2 = #{finprodType2}
AND AD.PROD_REGIST_CODE IS NOT NULL
ORDER BY AD.UPDATE_TIME DESC

SELECT ACCT_NO
FROM PTL_CAPACCT_INFO


		AND PORTFOLIO_ID = #{portfolioId}


		AND ACCT_TYPE = #{acctType}


		AND CCY = #{ccy}

    with PTL as
		 (SELECT max(TDY_INTINCEXP) TDY_INTINCEXP, PORTFOLIO_ID, FINPROD_ID
		    FROM PTL_SEC_VALUTION
		   WHERE CDATE = #{lastDay,jdbcType=DATE}
				and PORTFOLIO_ID = #{portfolioId}
				and FINPROD_ID = #{busiAcctNo}
		   GROUP BY PORTFOLIO_ID, FINPROD_ID)
	select
		NVL(PTL.TDY_INTINCEXP,0)
		- (SELECT
			NVL(SUM(NVL(T2.TRADE_AMT, 0)),0)
			FROM
				PTL_TRADE T1
			INNER JOIN
				TRD_PRODUCT_DEAL T2
			ON
				T1.BUSI_NO = T2.TRADE_ID
				AND T1.BUSI_TYPE = #{BUSI_TYPE}
				AND T2.TRADE_STATUS = #{TRADE_STATUS_01}
				AND T2.IS_CANCEL = #{IS_CANCEL_N}
				AND T2.MDATE = to_date(#{mdate},'yyyy-mm-dd')
			WHERE
				T1.PORTFOLIO_ID = #{portfolioId}
				AND T1.BUSI_ID = #{busiAcctNo}
				)  TRADE_AMT
  	from PTL

		PTL.PORTFOLIO_ID = #{portfolioId}
		and PTL.FINPROD_ID = #{busiAcctNo}
